from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    tokens = rule.split()
    kind = tokens[0]
    step = int(tokens[1])
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * step)).isoformat()
            for i in range(count)
        ]

    result = []

    if kind == "WEEKLY":
        selected = sorted(weekdays[wd] for wd in tokens[2].split(","))
        monday = first - timedelta(days=first.weekday())

        while True:
            for wd in selected:
                candidate = monday + timedelta(days=wd)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            monday += timedelta(weeks=step)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        ordinal = int(tokens[2])
        target_weekday = weekdays[tokens[3]] if len(tokens) == 4 else None

        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            last_day = monthrange(year, month)[1]

            if target_weekday is None:
                day = last_day if ordinal == -1 else ordinal
            elif ordinal == -1:
                last_weekday = date(year, month, last_day).weekday()
                day = last_day - (last_weekday - target_weekday) % 7
            else:
                first_weekday = date(year, month, 1).weekday()
                day = (
                    1
                    + (target_weekday - first_weekday) % 7
                    + 7 * (ordinal - 1)
                )

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())

            month_index += step

        return result

    month, day = map(int, tokens[2].split("-"))
    year = first.year

    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= first:
                result.append(candidate.isoformat())
        year += step

    return result
